    }
    private func avatarBarButton() -> UIBarButtonItem { let button = UIButton(type: .system); button.setImage(UIImage(named: member.image)?.withRenderingMode(.alwaysOriginal), for: .normal); button.imageView?.contentMode = .scaleAspectFill; button.round(17); button.widthAnchor.constraint(equalToConstant: 34).isActive = true; button.heightAnchor.constraint(equalToConstant: 34).isActive = true; button.accessibilityLabel = "Open \(member.name)'s profile"; button.addTarget(self, action: #selector(openProfile), for: .touchUpInside); return UIBarButtonItem(customView: button) }
