    @objc private func sendMessage() { guard let text = field.text?.trimmingCharacters(in: .whitespacesAndNewlines), !text.isEmpty else { return }; guard LookMeContentPolicy.allows(text) else { present(LMNoticeViewController(style: .warning, title: "Message not sent", message: "Please revise content that may be unsafe, explicit, threatening or spam-like."), animated: true); return }; guardMutual { [weak self] in guard let self else { return }; LookMeExperienceStore.shared.send(text, to: member.id); field.text = "" } }
    @objc private func voiceCall() { guardMutual { [weak self] in guard let self else { return }; CallPermissionManager.request(video: false, from: self) { self.present(VideoCallViewController(member: self.member, mode: .voice), animated: true) } } }
    @objc private func videoCall() { guardMutual { [weak self] in guard let self else { return }; CallPermissionManager.request(video: true, from: self) { self.present(VideoCallViewController(member: self.member, mode: .video), animated: true) } } }
    @objc private func openProfile() { navigationController?.pushViewController(CommunityProfileDetailViewController(member: member), animated: true) }
    @objc private func safety() { SafetyCoordinator.present(from: self, target: .init(id: "chat:\(member.id)", type: "conversation", userID: member.id, displayName: member.name)) }
    private func guardMutual(_ action: () -> Void) { guard LookMeExperienceStore.shared.isMutual(with: member.id) else { present(LMNoticeViewController(style: .warning, title: "Mutual follow required", message: "You and \(member.name) must both choose to follow each other before messaging or calling."), animated: true); return }; action() }
    private func scrollBottom() { DispatchQueue.main.async { guard !self.messages.isEmpty else { return }; self.table.scrollToRow(at: IndexPath(row: self.messages.count - 1, section: 0), at: .bottom, animated: true) } }
}

final class MessageBubbleCell: UITableViewCell {
    private let bubble = UIView(); private let label = UILabel.lm(size: 14, weight: .medium); private let time = UILabel.lm(size: 9, color: LMTheme.muted); private let avatar = UIImageView(); private var leading: NSLayoutConstraint!; private var trailing: NSLayoutConstraint!; private var avatarLeading: NSLayoutConstraint!
    override init(style: UITableViewCell.CellStyle, reuseIdentifier: String?) {
        super.init(style: style, reuseIdentifier: reuseIdentifier); backgroundColor = .clear; selectionStyle = .none
        avatar.contentMode = .scaleAspectFill; avatar.round(13); avatar.translatesAutoresizingMaskIntoConstraints = false; contentView.addSubview(avatar)
        bubble.round(17); bubble.translatesAutoresizingMaskIntoConstraints = false; contentView.addSubview(bubble); label.numberOfLines = 0; label.translatesAutoresizingMaskIntoConstraints = false; time.translatesAutoresizingMaskIntoConstraints = false; bubble.addSubview(label); bubble.addSubview(time)
        leading = bubble.leadingAnchor.constraint(equalTo: contentView.leadingAnchor, constant: 48); trailing = bubble.trailingAnchor.constraint(equalTo: contentView.trailingAnchor, constant: -14); avatarLeading = avatar.leadingAnchor.constraint(equalTo: contentView.leadingAnchor, constant: 14)
        NSLayoutConstraint.activate([bubble.topAnchor.constraint(equalTo: contentView.topAnchor, constant: 6), bubble.bottomAnchor.constraint(equalTo: contentView.bottomAnchor, constant: -6), bubble.widthAnchor.constraint(lessThanOrEqualTo: contentView.widthAnchor, multiplier: 0.72), label.topAnchor.constraint(equalTo: bubble.topAnchor, constant: 10), label.leadingAnchor.constraint(equalTo: bubble.leadingAnchor, constant: 13), label.trailingAnchor.constraint(equalTo: bubble.trailingAnchor, constant: -13), time.topAnchor.constraint(equalTo: label.bottomAnchor, constant: 4), time.trailingAnchor.constraint(equalTo: bubble.trailingAnchor, constant: -11), time.bottomAnchor.constraint(equalTo: bubble.bottomAnchor, constant: -7), avatarLeading, avatar.bottomAnchor.constraint(equalTo: bubble.bottomAnchor), avatar.widthAnchor.constraint(equalToConstant: 26), avatar.heightAnchor.constraint(equalTo: avatar.widthAnchor)])
    }
