    func configure(_ message: DirectConversationEntry, avatar imageName: String) { label.text = message.text; time.text = DateFormatter.chatTime.string(from: message.sentAt); bubble.backgroundColor = message.isMine ? LMTheme.pink : LMTheme.panel2; time.textColor = message.isMine ? .white.withAlphaComponent(0.67) : LMTheme.muted; leading.isActive = !message.isMine; trailing.isActive = message.isMine; avatar.isHidden = message.isMine; avatar.image = UIImage(named: imageName) }
